// Server-authoritative catalog for the AI Tools (Dream Tools) workspace tab.
// The web client renders this list and POSTs a tool id back, so a listed tool is
// always a tool the platform can actually run.

export type DreamTool = {
  id: string;
  label: string;
  category: string;
  icon: string;
  summary: string;
  inputLabel: string;
  placeholder: string;
  prompt: string;
};

export const DREAM_TOOL_INPUT_LIMIT = 12000;

export const DREAM_TOOL_CATEGORIES = [
  "Career",
  "Writing",
  "Finance",
  "Health",
  "Learning",
  "Creative",
  "Legal",
  "Relationships",
  "Productivity",
  "Business",
  "Fun",
] as const;

const BASE_RULES = [
  "Answer in the same language the user wrote in.",
  "Use only the details the user gave you; if something essential is missing, make one reasonable assumption and state it in a single short line at the top.",
  "Never invent facts, numbers, employers, diagnoses, citations or quotes about the user.",
  "Deliver the finished artifact itself, not a plan describing what you would write.",
  "Keep formatting clean Markdown: short paragraphs, headings only where they help, no filler preamble and no closing summary.",
].join(" ");

function tool(
  id: string,
  label: string,
  category: string,
  icon: string,
  summary: string,
  inputLabel: string,
  placeholder: string,
  role: string,
): DreamTool {
  return { id, label, category, icon, summary, inputLabel, placeholder, prompt: role + " " + BASE_RULES };
}

