const INDEX = new Map(DREAM_TOOLS.map(entry => [entry.id, entry]));

export function dreamToolById(id: unknown): DreamTool | undefined {
  return typeof id === "string" ? INDEX.get(id) : undefined;
}

export function dreamToolCatalog() {
  return DREAM_TOOLS.map(({ prompt, ...rest }) => rest);
}
